/* Actual manager scan/enable/stop/resume; synthetic directory and GUI only. */
#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "fenestra_module_manager.h"
static uint8_t fw[32],package[156];static uint32_t cursor,renames,rev;static char names[2][32]={"framing.wlm","prores.wlm.disabled"};
static void put(uint8_t *p,uint32_t n){for(uint32_t i=0;i<4u;++i)p[i]=(uint8_t)(n>>(8u*i));}
static void make(void){memset(fw,0xa5,32);memcpy(package,"FENESTRA",8);put(package+8,2);put(package+12,128);put(package+16,1);put(package+20,1);memcpy(package+24,fw,32);put(package+88,156);put(package+92,4096);put(package+100,1);put(package+116,1);put(package+132,152);put(package+136,4);put(package+140,4096);put(package+144,5);put(package+148,4096);put(package+152,0xd65f03c0);fx_sha256(package+128,28,package+56);}
static FxResult open_dir(void *p){(void)p;cursor=0;return FX_OK;}static FxResult next(void *p,FxModuleDirectoryEntry *e){(void)p;if(cursor==2)return FX_EMPTY;memset(e,0,sizeof(*e));memcpy(e->name,names[cursor++],32);e->bytes=156;return FX_OK;}static FxResult close_dir(void *p){(void)p;return FX_OK;}static FxResult read_file(void *p,const char *name,uint8_t *out,uint32_t cap,uint32_t *bytes){(void)p;(void)name;assert(cap>=156);memcpy(out,package,156);*bytes=156;return FX_OK;}static FxResult rename_file(void *p,const char *from,const char *to){(void)p;for(uint32_t i=0;i<2;++i)if(!strcmp(from,names[i])){memset(names[i],0,32);memcpy(names[i],to,strlen(to));++renames;return FX_OK;}return FX_EMPTY;}
static uint32_t current(void *p,const char *id){(void)p;return !strcmp(id,"framing");}static void *alloc(void *p,uint32_t n){(void)p;return malloc(n);}static void release(void *p,void *x){(void)p;free(x);}
FxResult fx_platform_init(FxPlatformOwner *o,const FxPlatform *p,uint32_t owner,uint32_t gen,uint32_t caps){(void)p;(void)owner;(void)gen;(void)caps;memset(o,0,sizeof(*o));return FX_OK;}
FxResult fx_platform_dispatch(FxPlatformOwner *o,const FxServiceRequest *q,FxServiceReply *a){(void)o;memset(a,0,sizeof(*a));if(q->arg[0]==FX_UI_GET)return FX_EMPTY;a->value[0]=++rev;return FX_OK;}
FxResult fx_ui_poll_message(FxPlatformOwner *o,void *p,uint32_t cap,uint32_t *bytes){(void)o;(void)p;(void)cap;*bytes=0;return FX_EMPTY;}
int main(void){make();FxModuleManager m;FxPlatform p={.abi=1};memcpy(p.module_identity,fw,32);FxModuleManagerIO io={.directory={0,open_dir,next,close_dir,read_file},.rename=rename_file,.current=current,.memory={0,alloc,release}};assert(fx_module_manager_init(&m,&p,&io,0)==FX_OK);assert(m.activated==1);assert(fx_module_manager_scan(&m)==FX_OK);assert(m.count==2&&m.entries[0].current==1&&m.entries[1].current==0);assert(fx_module_manager_enable(&m,0,0)==FX_OK);assert(m.entries[0].enabled==0&&m.entries[0].current==1);fx_module_manager_shutdown(&m);assert(fx_module_manager_resume(&m)==FX_OK&&m.activated==1);assert(fx_module_manager_scan(&m)==FX_OK);assert(m.entries[0].enabled==0&&m.entries[0].current==1);assert(fx_module_manager_enable(&m,1,1)==FX_OK);assert(m.entries[1].enabled==1&&m.entries[1].current==0);assert(renames==2);assert(fx_module_manager_freeze(&m)==FX_OK&&m.loading==1&&m.activated==1);fx_module_manager_ready(&m);assert(!m.loading&&m.entries[0].current==1&&m.entries[1].current==0);puts("PASS: actual manager warm Resume retains frozen current selection; next-cold disable/enable and ready projection do not masquerade as current");return 0;}
